if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/course/lib.php');
require_once($CFG->dirroot . '/mod/attendance/lib.php');
try {
    $course = $DB->get_record('course', ['shortname' => 'ATTDEMO01'], '*', MUST_EXIST);
    $module = $DB->get_record('modules', ['name' => 'attendance'], '*', MUST_EXIST);
    $admin = get_admin();
    \core\session\manager::set_user($admin);
    $now = time();
    $cm = (object)[
        'course'       => $course->id,
        'module'       => $module->id,
        'instance'     => 0,
        'section'      => 1,
        'idnumber'     => '',
        'added'        => $now,
        'score'        => 0,
        'indent'       => 0,
        'visible'      => 1,
        'visibleold'   => 1,
        'groupmode'    => 0,
        'groupingid'   => 0,
        'completion'   => 0,
        'showdescription' => 0,
    ];
    $cmid = add_course_module($cm);
    $attendance = (object)[
        'course'       => $course->id,
        'coursemodule' => $cmid,
        'name'         => 'Sample attendance register',
        'intro'        => '<p>Open this attendance activity to try the <strong>mod_attendance</strong> workflow: add sessions, take attendance for the demo student, and explore the reports tab.</p>',
        'introformat'  => FORMAT_HTML,
        'grade'        => 100,
        'subnet'       => '',
        'sessiondetailspos' => 'left',
        'showsessiondescriptiononreport' => 0,
    ];
    $instanceid = attendance_add_instance($attendance);
    $DB->set_field('course_modules', 'instance', $instanceid, ['id' => $cmid]);
    course_add_cm_to_section($course->id, $cmid, 1);
    rebuild_course_cache($course->id, true);
    echo "Created mod_attendance instance id={$instanceid} cmid={$cmid} in course {$course->shortname}\n";
} catch (\Throwable $e) {
    echo 'ERROR: ' . $e->getMessage() . "\n";
}
